/* -----------------------------------------------------------------------------
 * https://developer.chrome.com/docs/extensions/reference/api/i18n#locales
 * -----------------------------------------------------------------------------
 */

// generated by:
//   JSON.stringify([...document.querySelectorAll('#locales + p + p + div.devsite-table-wrapper > table > tbody > tr > td:first-child')].map(el => el.textContent.trim()).sort())
const supported = ["am","ar","bg","bn","ca","cs","da","de","el","en","en_AU","en_GB","en_US","es","es_419","et","fa","fi","fil","fr","gu","he","hi","hr","hu","id","it","ja","kn","ko","lt","lv","ml","mr","ms","nl","no","pl","pt_BR","pt_PT","ro","ru","sk","sl","sr","sv","sw","ta","te","th","tr","uk","vi","zh_CN","zh_TW"]

const get_code = (lcode, rcode) => {
  return rcode
    ? `${lcode}_${rcode}`
    : lcode
}

const is_supported = (lcode, rcode) => supported.includes(get_code(lcode, rcode))

const get_webextension_resource_directory_name = (output_language_code) => {
  // enforce the convention:
  //   - lowercase language code
  //   - uppercase region code
  let [lcode, rcode] = output_language_code.split('-')

  if (!lcode)
    throw new Error('invalid output language code')

  lcode = lcode.toLowerCase()

  switch(lcode) {
    case 'zt':
      lcode = 'zh'
      rcode = 'TW'
      break
  }

  if (!rcode) {
    switch(lcode) {
      case 'pt':
        rcode = 'PT'
        break
      case 'zh':
        rcode = 'CN'
        break
    }
  }

  if (rcode) {
    rcode = rcode.toUpperCase()

    if (lcode === 'zh') {
      switch(rcode) {
        case 'HANS':
          rcode = 'CN'
          break
        case 'HANT':
          rcode = 'TW'
          break
      }
    }

    if (lcode === 'es') {
      switch(rcode) {
        // https://support.apple.com/es-us/guide/apple-business-connect/abcb88b4fea6/web
        case 'AR':
        case 'BO':
        case 'CL':
        case 'CO':
        case 'CR':
        case 'EC':
        case 'SV':
        case 'GT':
        case 'HN':
        case 'MX':
        case 'NI':
        case 'PA':
        case 'PY':
        case 'PE':
        case 'UY':
        case 'VE':
          rcode = '419'
          break
      }
    }

    if (!is_supported(lcode, rcode))
      rcode = null
  }

  if (!is_supported(lcode, rcode))
    throw new Error('invalid output language code')

  return get_code(lcode, rcode)
}

module.exports = get_webextension_resource_directory_name
